// ── Real holidays: the town celebrates the days you do ────────────────────────────────────────────────────────────

/** Seollal and Chuseok move with the moon: the day itself (the town keeps the day before and after, too). */
const LUNAR = {
  2026: { seol: '02-17', chuseok: '09-25' },
  2027: { seol: '02-07', chuseok: '09-15' },
  2028: { seol: '01-26', chuseok: '10-03' },
  2029: { seol: '02-13', chuseok: '09-22' },
  2030: { seol: '02-03', chuseok: '09-12' },
};
const HOLIDAY_LINES = {
  seol: '설날이에요! 마을 사람들이 한복을 입고 세배를 다녀요.',
  chuseok: '추석이에요! 보름달 아래 송편을 빚어요.',
  newyear: '새해 첫날이에요! 밤하늘에 불꽃이 터져요.',
  cherry: '벚꽃이 피었어요! 꽃잎이 바람에 날려요.',
  children: '어린이날이에요! 하늘에 풍선이 날아올라요.',
  halloween: '핼러윈이에요! 집집마다 호박등을 켰어요.',
  xmas: '메리 크리스마스! 광장에 큰 트리가 섰어요.',
  yearend: '한 해의 마지막 날이에요. 다들 수고했어요!',
};
const HOLIDAY_NAMES = { seol: '설날', chuseok: '추석', newyear: '새해', cherry: '벚꽃 주간', children: '어린이날', halloween: '핼러윈', xmas: '크리스마스', yearend: '연말' };

function holidayOn(date = new Date()) {
  const md = `${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`;
  const near = (target) => {
    if (!target) return false;
    const [m, d] = target.split('-').map(Number);
    const t = new Date(date.getFullYear(), m - 1, d);
    return Math.abs((new Date(date.getFullYear(), date.getMonth(), date.getDate()) - t) / 86_400_000) <= 1;
  };
  const lunar = LUNAR[date.getFullYear()];
  if (near(lunar?.seol)) return 'seol';
  if (near(lunar?.chuseok)) return 'chuseok';
  if (md === '01-01') return 'newyear';
  if (md >= '03-28' && md <= '04-08') return 'cherry';
  if (md === '05-05') return 'children';
  if (md === '10-31') return 'halloween';
  if (md === '12-24' || md === '12-25') return 'xmas';
  if (md === '12-31') return 'yearend';
  return null;
}
let holiday = null;
/** Once a day: is it a holiday? Then a festival, a story and a photo. */
function checkHoliday() {
  holiday = holidayOn();
  if (!holiday || MODE !== 'life' || !S.gender) return;
  if (S.holidayDay === today()) return;
  S.holidayDay = today();
  S.festival = today();
  story(`🎉 ${HOLIDAY_LINES[holiday]}`);
  photoSoon(HOLIDAY_NAMES[holiday]);
}

let petals = []; // cherry petals, balloons, snow on Christmas
function holidayTick(k) {
  if (!holiday) return;
  const kind = holiday === 'cherry' ? 'petal' : holiday === 'children' ? 'balloon' : holiday === 'xmas' ? 'snow' : null;
  if (!kind) return;
  if (petals.length < (kind === 'balloon' ? 8 : 30) && Math.random() < 0.5 * k)
    petals.push({
      x: viewX + Math.random() * VIEW_W,
      y: kind === 'balloon' ? H + 10 : -4,
      vx: kind === 'petal' ? 0.4 + Math.random() * 0.4 : (Math.random() - 0.5) * 0.3,
      vy: kind === 'balloon' ? -0.5 - Math.random() * 0.4 : 0.4 + Math.random() * 0.4,
      c: kind === 'balloon' ? ['#ff6b6b', '#ffd23f', '#5ab4e0', '#8a6cc9', '#5cb84e'][Math.floor(Math.random() * 5)] : null,
      kind,
    });
  petals = petals.filter((p) => {
    p.x += (p.vx + Math.sin((p.y + p.x) / 20) * 0.2) * k;
    p.y += p.vy * k;
    return p.y > -20 && p.y < H + 20;
  });
}
function drawHoliday(g) {
  if (!holiday || MODE === 'chaos') return;
  const night = isNight();
  const blink = Math.floor(clockTick() / 4) % 2;
  // Lanterns (Seollal, Chuseok) or lights (Christmas, year's end) strung along the road near the square.
  if (['seol', 'chuseok', 'xmas', 'yearend', 'newyear'].includes(holiday)) {
    const from = (PLAZA.x - 10) * T;
    const to = (PLAZA.x + 16) * T;
    for (let x = from; x < to; x += 12) {
      if (x < viewX - 12 || x > viewX + VIEW_W + 12) continue;
      const sag = Math.round(Math.sin(((x - from) / 24) * Math.PI) * 2);
      const y = ROAD_Y * T - 22 + sag;
      R(g, x, y - 1, 12, 1, '#6a5a50');
      const lantern = holiday === 'seol' || holiday === 'chuseok';
      const c = lantern ? ((x / 12) % 2 ? '#e8504a' : '#f0a030') : ['#ff5a5a', '#5ad75a', '#ffd23f', '#5ab4ff'][(x / 12 + blink) % 4];
      if (lantern) {
        box(g, x + 4, y, 4, 5, c, '#8a3a2a');
        if (night) disc(g, x + 6, y + 2, 4, 'rgba(255, 200, 120, 0.25)');
      } else R(g, x + 5, y, 2, 2, c);
    }
  }
  // A full moon for Chuseok.
  if (holiday === 'chuseok' && night) {
    disc(g, viewX + VIEW_W - 34, 26, 11, 'rgba(255, 240, 190, 0.25)');
    disc(g, viewX + VIEW_W - 34, 26, 8, '#fff2c4');
  }
  // Pumpkins by the nearest houses.
  if (holiday === 'halloween')
    for (let i = 0; i < Math.min(8, S.houses); i++) {
      const tx = lotX(i);
      if (!onScreen(tx * T)) continue;
      const x = tx * T + 20;
      const y = lotBottom(i) - 9;
      box(g, x, y, 11, 9, '#f08a2a', '#a0501a');
      R(g, x + 3, y + 1, 1, 7, '#d8701e'); // ridges
      R(g, x + 7, y + 1, 1, 7, '#d8701e');
      R(g, x + 5, y - 3, 2, 3, '#3f7a3a');
      R(g, x + 7, y - 2, 2, 1, '#5a9a4a'); // leaf
      if (night || blink) {
        if (night) disc(g, x + 5, y + 4, 7, 'rgba(255, 170, 60, 0.18)');
        R(g, x + 2, y + 2, 2, 2, '#ffe066');
        R(g, x + 7, y + 2, 2, 2, '#ffe066');
        R(g, x + 2, y + 6, 7, 1, '#ffe066');
        R(g, x + 3, y + 5, 1, 1, '#ffe066');
        R(g, x + 7, y + 5, 1, 1, '#ffe066');
      }
    }
  // A Christmas tree in the square.
  if (holiday === 'xmas') {
    const x = (PLAZA.x + 5) * T + 4;
    const y = (PLAZA.y + 2) * T - 2;
    if (night) disc(g, x, y - 22, 20, 'rgba(255, 220, 140, 0.12)');
    // Five tiers, narrow at the top; a pot under the trunk.
    for (let i = 0; i < 5; i++) box(g, x - 3 - i * 3, y - 40 + i * 7, 7 + i * 6, 8, '#2f7a3a', '#1f5a2a');
    R(g, x - 2, y - 5, 5, 3, '#7a4a2a');
    box(g, x - 4, y - 3, 9, 5, '#c8402e', '#8a2a1e');
    // Garland zigzags and blinking baubles.
    for (let i = 0; i < 4; i++) for (let k = -4 - i * 3; k <= 4 + i * 3; k += 2) R(g, x + k, y - 32 + i * 7 + ((k >> 1) & 1), 1, 1, '#f2d27a');
    const lights = ['#ff5a5a', '#5ab4ff', '#ffd23f', '#ff8ac0'];
    for (let t = 1, n = 0; t < 5; t++)
      for (let k = 0; k <= t; k++, n++) R(g, x - t * 3 + Math.round((k * t * 6) / Math.max(1, t)) - (k ? 1 : 0), y - 38 + t * 7 + (k & 1) * 2, 2, 2, lights[(n + blink) % 4]);
    // The star.
    R(g, x, y - 46, 1, 5, '#ffd23f');
    R(g, x - 2, y - 44, 5, 1, '#ffd23f');
    R(g, x - 1, y - 45, 3, 3, '#ffd23f');
    if (night || blink) disc(g, x, y - 44, 4, 'rgba(255, 230, 120, 0.3)');
    // Presents.
    box(g, x - 13, y - 3, 6, 5, '#5ab4ff', '#2a6a9a');
    R(g, x - 11, y - 3, 1, 5, '#ffffff');
    box(g, x + 7, y - 2, 5, 4, '#ffd23f', '#a0801a');
    R(g, x + 9, y - 2, 1, 4, '#c8402e');
  }
  for (const p of petals) {
    const x = Math.round(p.x);
    const y = Math.round(p.y);
    if (p.kind === 'petal') R(g, x, y, 2, 1, '#ffc0d6');
    else if (p.kind === 'snow') R(g, x, y, 1, 1, '#ffffff');
    else {
      disc(g, x, y, 3, p.c);
      R(g, x, y + 3, 1, 6, '#8a8a92');
    }
  }
}

// ── Rare colours: now and then an animal is born golden, black, white or pink ─────────────────────────────────────

const VARIANTS = [
  { id: 'golden', name: '황금', to: (c) => mixHex(c, '#ffcf3a', 0.55) },
  { id: 'black', name: '까만', to: (c) => mixHex(c, '#2a2630', 0.65) },
  { id: 'white', name: '새하얀', to: (c) => mixHex(c, '#ffffff', 0.7) },
  { id: 'pink', name: '분홍', to: (c) => mixHex(c, '#ff8ac0', 0.5) },
];
const ANIMAL_NAMES = {
  chicken: '닭', cow: '소', sheep: '양', pig: '돼지', goat: '염소', horse: '말', alpaca: '알파카', donkey: '당나귀', turkey: '칠면조',
  duck: '오리', rabbit: '토끼', deer: '사슴', fox: '여우', squirrel: '다람쥐', frog: '개구리', cat: '고양이', hedgehog: '고슴도치',
  turtle: '거북이', swan: '백조', boar: '멧돼지', bear: '곰', raccoon: '너구리',
};
const VARIANT_TOTAL = Object.keys(ANIMAL_NAMES).length * VARIANTS.length;
function mixHex(a, b, t) {
  if (typeof a !== 'string' || a[0] !== '#' || a.length !== 7) return a;
  const pa = parseInt(a.slice(1), 16);
  const pb = parseInt(b.slice(1), 16);
  const ch = (s) => Math.round(((pa >> s) & 255) * (1 - t) + ((pb >> s) & 255) * t);
  return `#${[16, 8, 0].map((s) => ch(s).toString(16).padStart(2, '0')).join('')}`;
}
/** The same animal (kind + how many of its kind came before it) keeps its colour for this map. */
function variantFor(kind, n) {
  if (!ANIMAL_NAMES[kind]) return null;
  let h = (S.mapSeed ?? 0) + n * 7919;
  for (const ch of kind) h = (h * 31 + ch.charCodeAt(0)) >>> 0;
  const r = rng(h);
  if (r() >= 0.05) return null;
  return VARIANTS[Math.floor(r() * VARIANTS.length)].id;
}
/** A palette in the animal's rare colour (outlines and eyes stay). */
const variantCache = new Map();
function variantPal(pal, v) {
  let m = variantCache.get(pal);
  if (!m) variantCache.set(pal, (m = new Map()));
  if (m.has(v)) return m.get(v);
  const vv = VARIANTS.find((x) => x.id === v);
  const out = Object.fromEntries(Object.entries(pal).map(([k, c]) => [k, ['o', 'e', 'n', 'E'].includes(k) || !vv ? c : vv.to(c)]));
  m.set(v, out);
  return out;
}
/** Tag the town's animals with their colours; a story the first time a colour shows up. */
function tagVariants(list) {
  const count = {};
  for (const a of list) {
    const n = (count[a.kind] = (count[a.kind] ?? 0) + 1);
    a.variant = variantFor(a.kind, n);
    if (!a.variant || MODE !== 'life') continue;
    const key = `${a.kind}:${a.variant}`;
    S.variants ??= [];
    if (S.variants.includes(key)) continue;
    S.variants.push(key);
    story(`✨ 희귀한 ${VARIANTS.find((v) => v.id === a.variant).name} ${ANIMAL_NAMES[a.kind]}이(가) 나타났어요!`);
  }
}
  // ── aquila/visit.js
// 작은 마을 — 놀러가기: visit a friend's town with a code, no server.
// A life town is only looked at (your character walks around it, you can leave a guestbook note that goes back as a
// short reply code). A chaos town can be broken by both of you: the code carries the whole sandbox, so you wreck it
// and send it back, and so on. Your own town is put aside untouched while you visit, and nothing you visit is saved.

let VISIT = null; // { home, host, chaos } while you're in someone else's town
let nick = ''; //    the name your friends see
let guests = []; //  other people's characters walking around this town (not saved)
let replyCode = ''; // after a guestbook note: the code to send back
const CODE_HEAD = '작은마을1:';
const GUESTBOOK_MAX = 8;

// ── The code: JSON → deflate → base64, with a head so a pasted message can be found ───────────────────────────────

async function pipeBytes(bytes, stream) {
  return new Uint8Array(await new Response(new Blob([bytes]).stream().pipeThrough(stream)).arrayBuffer());
}
/** Raw deflate both ways: the browser's streams, or a host's own (the Claude Code mod has no streams). */
const zipBytes = (bytes) => (window.VILLAGE_ZIP ? window.VILLAGE_ZIP.deflate(bytes) : pipeBytes(bytes, new CompressionStream('deflate-raw')));
const unzipBytes = (bytes) => (window.VILLAGE_ZIP ? window.VILLAGE_ZIP.inflate(bytes) : pipeBytes(bytes, new DecompressionStream('deflate-raw')));
async function packCode(obj) {
  const z = await zipBytes(new TextEncoder().encode(JSON.stringify(obj)));
  let s = '';
  for (let i = 0; i < z.length; i += 0x8000) s += String.fromCharCode(...z.subarray(i, i + 0x8000));
  return CODE_HEAD + btoa(s) + '.'; // the dot ends the code, whatever chat follows it
}
async function unpackCode(text) {
  const all = String(text ?? '');
  const at = all.indexOf(CODE_HEAD);
  if (at < 0) return null;
  // A messenger may wrap the code over lines, and chat may follow it. New codes end with a dot; for older ones,
  // try the longest run of whitespace-separated pieces that decodes (chat glued on fails to inflate).
  const rest = all.slice(at + CODE_HEAD.length);
  const dot = rest.indexOf('.');
  const pieces = (dot >= 0 ? rest.slice(0, dot) : rest).split(/\s+/).filter(Boolean);
  for (let n = pieces.length; n > 0; n--) {
    const body = /^[A-Za-z0-9+/]+=*/.exec(pieces.slice(0, n).join(''))?.[0];
    if (!body) continue;
    try {
      const bin = atob(body);
      const raw = await unzipBytes(Uint8Array.from(bin, (c) => c.charCodeAt(0)));
      const obj = JSON.parse(new TextDecoder().decode(raw));
      if (obj && typeof obj === 'object') return obj;
    } catch {
      /* shorter */
    }
    if (dot >= 0) break; // a dotted code is exactly that much
  }
  return null;
}

/** Your own life town, wherever you are right now. */
const homeState = () => VISIT?.home ?? (MODE === 'chaos' ? lifeState : null) ?? S;

/** Who you are, as a friend sees you: your name and your character's look. */
function myCard() {
  const h = homeState();
  return { name: nick || '이웃', gender: h.gender ?? 'f', style: h.style ?? null, era: h.era ?? 0 };
}

/** This town without what only matters to its owner (usage baseline, the long story). */
function townForCode() {
  const t = { ...S };
  for (const k of ['usage', 'story', 'chronicle', 'hall', 'merchant', 'over']) delete t[k];
  return t;
}

const myCode = () => packCode({ k: MODE === 'chaos' ? 'chaos' : 'town', from: myCard(), town: townForCode() });

// ── Other people's characters ──────────────────────────────────────────────────────────────────────────────────────

function guestLook(card) {
  const base = OUTFIT[Math.max(0, Math.min(OUTFIT.length - 1, card.era ?? 0))];
  const st = card.style ?? {};
  return { ...base, hair: st.hairColor ?? base.hair, top: st.top?.c ?? base.top, style: st.hair ?? undefined };
}
function addGuest(card) {
  if (!card) return;
  const g = make('guest', HOME_DOOR, {
    look: guestLook(card),
    gender: card.gender === 'm' ? 'm' : 'f',
    name: String(card.name ?? '이웃').slice(0, 8),
    speed: 1,
    needs: { energy: 100, hunger: 100, social: 100 },
  });
  guests.push(g);
  people.push(g);
}
/** spawnFamily() starts the crowd over: the guests stay. */
const guestPeople = () => guests;

/** A guest strolls up and down the street near the house, stopping now and then. */
function guestThink(e) {
  if (e.path.length) return step(e);
  if (e.wait > 0) {
    e.wait--;
    return false;
  }
  const near = me.hidden ? HOME.x : Math.round(me.x / T);
  const x = Math.max(1, Math.min(COLS - 2, near + Math.floor(Math.random() * 24) - 12));
  route(e, [x, ROAD_Y]);
  e.wait = 10 + Math.floor(Math.random() * 30);
  return true;
}

/** Names over guests (and over you, while you visit). */
function drawVisit(g) {
  if (!guests.length && !VISIT) return;
  g.font = '6px sans-serif';
  const tag = (e, text, bg, up = 0) => {
    if (e.hidden || !onScreen(e.x)) return;
    const w = Math.min(50, g.measureText(text).width + 4);
    const x = Math.round(e.x - w / 2);
    const y = Math.round(e.y) - 34 - up;
    g.fillStyle = bg;
    g.fillRect(x, y, w, 8);
    g.fillStyle = '#ffffff';
    g.fillText(text, x + 2, y + 6, 46);
  };
  for (const e of guests) tag(e, e.name, 'rgba(40, 30, 30, 0.7)');
  if (VISIT && !me.hidden) tag(me, myCard().name, 'rgba(49, 130, 246, 0.85)', 9); // above your arrow
}

// ── Guestbook signs left by visitors (life towns; chaos towns have their own signs) ────────────────────────────────

function paintSigns(g, list) {
  for (const s of list ?? []) {
    R(g, s.x, s.y - 10, 1, 10, '#6b4428');
    box(g, s.x - 8, s.y - 16, 17, 7, '#e9d9b0', '#8a5a32');
    g.font = '6px sans-serif';
    const text = s.name ? `${s.name}: ${s.text}` : s.text;
    const w = Math.min(90, g.measureText(text).width + 4);
    g.fillStyle = 'rgba(40, 30, 30, 0.75)';
    g.fillRect(s.x - w / 2, s.y - 26, w, 9);
    g.fillStyle = '#ffffff';
    g.fillText(text, s.x - w / 2 + 2, s.y - 19.5, 86);
  }
}
function paintVisit(g) {
  if (MODE !== 'chaos') paintSigns(g, S.guestbook);
}

// ── Going over and coming back ─────────────────────────────────────────────────────────────────────────────────────

/** After S changed to another town: the map, the crowd, the view. */
function settleTown(chaos) {
  fx = [];
  fires = [];
  task = null;
  me.path = [];
  me.act = null;
  me.hidden = false;
  applyLayout(S.mapSeed);
  [me.x, me.y] = [HOME_DOOR[0] * T + T / 2, HOME_DOOR[1] * T + T - 2]; // their door, now that their map is laid out
  me.px = me.x;
  me.py = me.y;
  if (!chaos) carveGroves();
  ensureLots(S.houses + (S.ruins ?? 0));
  guests = [];
  spawnFamily();
  spawnAnimals();
  spawnCars();
  sites = [];
  addGuest(VISIT.host);
  if (chaos) chaosCam = (HOME.x + 1.5) * T - VIEW_W / 2;
  lifeCam = null;
  cache.dirty = true;
  for (const id of ['eraPick', 'mode', 'pick', 'over', 'signBox']) $(id).hidden = true;
  $('visitCard').hidden = true;
  replyCode = '';
}

/** Someone's life town: look around, walk, leave a note. */
function enterVisit(obj) {
  const mine = myCard();
  VISIT = { home: homeState(), host: obj.from, chaos: false };
  lifeState = null;
  MODE = 'visit';
  S = { ...fresh(), ...obj.town, usage: {}, story: [], over: null, sickDays: 0, gender: mine.gender, style: mine.style ?? fresh().style };
  settleTown(false);
  story(`🧳 ${VISIT.host?.name ?? '이웃'}님이 코드를 만든 순간의 마을에 놀러 왔어요. 주민들 움직임은 각자 화면에서 따로 흘러가요.`);
  document.body.dataset.mode = 'visit';
  $('visitHost').textContent = `${VISIT.host?.name ?? '이웃'}님의 ${ERAS[S.era]?.name ?? ''} 마을`;
  paintUi();
  wake();
}

/** Someone's chaos town: the tools work, and you send it back when you're done. */
function enterChaosVisit(obj) {
  const mine = myCard();
  const home = homeState();
  VISIT = { home, host: obj.from, chaos: true };
  lifeState = home; // leaveChaos() brings it back
  MODE = 'chaos';
  const era = Math.max(0, Math.min(ERAS.length - 1, obj.town?.era ?? 0));
  S = { ...sandboxFor(era), ...obj.town, story: [], gender: mine.gender, style: mine.style ?? fresh().style };
  S.wrecked ??= [];
  S.wreckedLm ??= [];
  S.scorch ??= [];
  S.signs ??= [];
  S.bananas ??= [];
  S.chaosStats ??= { houses: 0, people: 0, animals: 0 };
  settleTown(true);
  story(`😈 ${VISIT.host?.name ?? '이웃'}님이 보낸 ${ERAS[era].name} 마을이에요. 같이 부수고, 다 되면 코드를 돌려보내세요.`);
  document.body.dataset.mode = 'chaos';
  paintChaosUi();
  paintUi();
  wake();
}

function leaveVisit() {
  if (!VISIT) return;
  lifeState = VISIT.home;
  VISIT = null;
  guests = [];
  leaveChaos(); // the same way home: back to the life town, untouched
}

/** A note on a life town: it stays on your screen and goes back to its owner as a reply code. */
async function visitNote() {
  if (MODE !== 'visit' || !VISIT) return;
  const text = ($('signText').value || '잘 보고 가요').slice(0, 24);
  const x = Math.round(Math.max(12, Math.min(W - 12, me.x)));
  const y = (ROAD_Y + 2) * T + 8; // on the grass below the road, clear of name tags
  const name = myCard().name;
  S.guestbook = [...(S.guestbook ?? []), { x, y, text, name }].slice(-GUESTBOOK_MAX);
  $('signBox').hidden = true;
  cache.dirty = true;
  story(`✍️ 방명록: "${text}"`);
  replyCode = await packCode({ k: 'note', from: myCard(), seed: S.mapSeed, text, x, y });
  openVisitCard();
  paintUi();
}

/** A friend's note on your own town. */
function takeNote(obj) {
  if (MODE !== 'life') return toast('방명록 코드는 내 마을에서 열어 주세요');
  if (obj.seed !== S.mapSeed) return toast('다른 마을에 남긴 방명록이에요');
  const name = String(obj.from?.name ?? '이웃').slice(0, 8);
  const text = String(obj.text ?? '').slice(0, 24);
  const x = Math.round(Math.max(12, Math.min(W - 12, Number(obj.x) || HOME.x * T)));
  const y = Math.round(Number(obj.y) || (ROAD_Y + 2) * T + 8);
  S.guestbook = [...(S.guestbook ?? []), { x, y, text, name }].slice(-GUESTBOOK_MAX);
  addGuest(obj.from);
  story(`✍️ ${name}님이 놀러 와서 방명록을 남겼어요: "${text}"`);
  cache.dirty = true;
  save();
  paintUi();
  toast(`${name}님이 놀러 왔어요`);
}

async function openCode(text) {
  const obj = await unpackCode(text);
  if (!obj) return toast('코드를 읽지 못했어요. 끝까지 복사했는지 확인해 주세요', 2600);
  if (obj.k === 'note') return takeNote(obj);
  if (!obj.town || typeof obj.town !== 'object') return toast('코드를 읽지 못했어요', 2000);
  if (obj.k === 'town' && obj.town.mapSeed === homeState().mapSeed) return toast('내 마을 코드예요. 친구에게 보내 주세요');
  $('theirCode').value = '';
  if (obj.k === 'chaos') return enterChaosVisit(obj);
  if (obj.k === 'town') return enterVisit(obj);
  toast('코드를 읽지 못했어요');
}

// ── The page ───────────────────────────────────────────────────────────────────────────────────────────────────────

async function openVisitCard() {
  $('visitCard').hidden = false;
  $('nick').value = nick;
  const title = $('myCodeTitle');
  const note = $('myCodeNote');
  $('myCode').value = '';
  if (MODE === 'visit') {
    title.textContent = '방명록 코드';
    note.textContent = replyCode ? `${VISIT.host?.name ?? '친구'}님에게 보내면 방명록 팻말이 생겨요.` : '방명록을 남기면 여기에 코드가 생겨요.';
    $('myCode').value = replyCode;
  } else if (MODE === 'chaos') {
    title.textContent = VISIT ? '돌려보낼 코드' : '이 마을 코드';
    note.textContent = VISIT
      ? `${VISIT.host?.name ?? '친구'}님에게 보내면 지금 부서진 그대로 이어서 부술 수 있어요.`
      : '친구에게 보내면 지금 부서진 그대로 받아서 같이 부술 수 있어요.';
    $('myCode').value = await myCode();
  } else {
    title.textContent = '내 마을 초대 코드';
    note.textContent = '친구에게 보내면 지금 이 순간의 마을을 구경할 수 있어요. 실시간으로 이어지지는 않아요.';
    $('myCode').value = await myCode();
  }
  $('copyCode').disabled = !$('myCode').value;
}

async function copyCode() {
  const area = $('myCode');
  if (!area.value) return;
  try {
    await navigator.clipboard.writeText(area.value);
    toast('코드를 복사했어요');
  } catch {
    area.focus();
    area.select();
    toast('코드를 선택해 두었어요. ⌘C로 복사해 주세요', 2600);
  }
}

function wireVisit() {
  $('toVisit').addEventListener('click', () => ($('visitCard').hidden ? openVisitCard() : ($('visitCard').hidden = true)));
  $('visitClose').addEventListener('click', () => ($('visitCard').hidden = true));
  $('copyCode').addEventListener('click', copyCode);
  $('openCode').addEventListener('click', () => openCode($('theirCode').value));
  $('visitExit').addEventListener('click', leaveVisit);
  $('visitWrite').addEventListener('click', () => {
    $('signBox').hidden = false;
    $('signText').value = '';
    $('signText').focus();
  });
  $('nick').addEventListener('change', () => {
    nick = $('nick').value.trim().slice(0, 8);
    void aquila.storage.set('nick', nick).catch(() => {});
    if (!$('visitCard').hidden && MODE !== 'visit') void openVisitCard();
  });
  void aquila.storage
    .get('nick')
    .then((v) => (nick = typeof v === 'string' ? v : ''))
    .catch(() => {});
}
  // ── aquila/game.js
// 작은 마을 — a town that grows with your Claude / Codex usage, from a tent in a field to a future city.
// Nobody plays it: you farm, build, keep animals, make friends, marry and raise kids on your own while you work.
//
// Battery: the economy moves only when Aquila reports a usage change (no polling). The still parts of the picture are
// drawn once into a cache; people, animals and cars move at 8 frames a second only while the panel is on screen and
// not in power saver. Otherwise nothing is drawn and pending work is done at once (it shows in the story).

// ── Rules ──────────────────────────────────────────────────────────────────────────────────────────────────────────

const COINS_PER_WEEKLY_PCT = 10; // 1 % of a weekly limit used = 🪙10
